    expect(paused.goals).toHaveLength(goals);
    expect(paused.routines[0]?.heldBack).toEqual(["send"]);
    expect(paused.routines[0]?.nextRunAt).toBe(launchNext);
    expect(paused.routines[1]?.nextRunAt).toBe(secondNext);
