    expect(aside.routines[0]?.cadence).toBe("hourly");
    expect(aside.routines[0]?.nextRunAt).toBe(launchNext);
    expect(aside.routines[0]?.lastRunAt).toBe("2026-10-23T11:00:00.000Z");
