    expect(afterStop.routines[2]?.lastRunAt).toBeNull();
    expect(afterStop.routines[2]?.instruction).toBe("Summarize the launch risks");
    expect(afterStop.routines[0]?.lastRunAt).toBe("2026-10-23T11:00:00.000Z");
