    const manualAgain = await convene(stopped, "Wake the Market check routine manual", undefined, early);
    expect(manualAgain.messages.at(-1)?.text).toBe(
      "“Market check” already wakes that way. It wakes only when you run it. The next time was not moved. Another routine is unchanged. The instruction stays in the record. The last run stays. Nothing was run. Nothing was sent or spent.",
    );
    expect(manualAgain.routines[1]?.cadence).toBe("manual");
    expect(manualAgain.routines[1]?.nextRunAt).toBeNull();
    expect(manualAgain.routines[1]?.instruction).toBe("Compare the market landscape");
