    expect(desk.routines[0]?.nextRunAt).toBe("2026-10-23T11:00:00.000Z");
    const deskOn = await convene(desk, "Resume wakes", undefined, early);
    expect(deskOn.paused).toBe(false);
    expect(deskOn.routines[0]?.paused).toBe(true);
    expect(deskOn.routines[1]?.paused).toBe(true);
    const afterDesk = await wakeDue(deskOn, early);
