      expect(ordinary.routines[0]?.cadence).toBe("hourly");
      expect(ordinary.routines[0]?.nextRunAt).toBe(launchNext);
      expect(ordinary.routines[1]?.paused).toBe(false);
      expect(ordinary.routines[1]?.nextRunAt).toBe(secondNext);
      expect(ordinary.routines[2]?.paused).toBe(false);
