    expect(resumedDesk.paused).toBe(false);
    expect(resumedDesk.routines[0]?.paused).toBe(true);
    expect(resumedDesk.routines[1]?.paused).toBe(false);
    expect(resumedDesk.routines[0]?.nextRunAt).toBe(launchNext);

    const kept = structuredClone(state);
