    expect(kept.routines[0]?.heldBack).toEqual(["send"]);
    expect(kept.routines[1]?.paused).toBe(false);
    expect(kept.routines[2]?.paused).toBe(false);
    expect(kept.goals).toHaveLength(goals);
    await expect(convene(kept, "Resume the Market check routine", "goal_missing", early)).rejects.toThrow(
      /not in the record/,
    );
    expect(kept.goals).toHaveLength(goals);
    expect(kept.routines[2]?.paused).toBe(false);
    expect(kept.approvals.find((approval) => approval.goalId === firstId)?.scope).toBe("task");

    const byStop = await convene(state, "Stop the Market check routine", undefined, early);
    expect(byStop.routines[2]?.cadence).toBe("manual");
    expect(byStop.routines[2]?.paused).toBe(false);
