    expect(named.messages.at(-1)?.text).toBe(routineActiveAskCopy("Launch note", true, true));
    expect(named.messages.at(-1)?.text).toContain("“Launch note” is not active. A wake does not run it.");
    expect(named.routines[0]?.nextRunAt).toBe(launchNext);
    expect(named.routines[1]?.nextRunAt).toBe(marketNext);
    expect(named.routines[0]?.paused).toBe(true);
    expect(named.routines[1]?.paused).not.toBe(true);

    const marketAsk = await convene(setPaused(one, true, early), "Is the Market check routine active?", undefined, early);
    expect(marketAsk.paused).toBe(true);
    expect(marketAsk.messages.at(-1)?.text).toBe(routineActiveAskCopy("Market check", false, true));
