      expect(activeWords.messages.at(-1)?.text).not.toContain("is enabled");
      expect(activeWords.routines[0]?.paused).toBe(false);
      expect(activeWords.routines[0]?.nextRunAt).toBe("2026-10-24T02:00:00.000Z");
