    const enabledAsk = await convene(one, "Is the Launch note routine enabled?", undefined, early);
    expect(enabledAsk.messages.at(-1)?.text).toBe(routineEnabledAskCopy("Launch note", true, true));
    expect(enabledAsk.messages.at(-1)?.text).toContain("“Launch note” is not enabled. A wake does not run it.");
