    expect(marketAsk.routines[1]?.paused).not.toBe(true);
    expect(marketAsk.routines[1]?.nextRunAt).toBe(marketNext);

    const solo = structuredClone(one);
    solo.routines.splice(1, 1);
    const alone = await convene(solo, "What time zone is the Launch note routine using?", undefined, early);
    expect(alone.messages.at(-1)?.text).toBe(routineZoneCopy("Launch note", false));
