    expect(named.routines[1]?.paused).not.toBe(true);
    expect(named.routines[0]?.cadence).toBe("hourly");
    expect(named.routines[0]?.lastRunAt).toBe("2026-10-24T03:00:00.000Z");

    const quoted = await convene(one, "Which repository starts the “Launch note” routine?", undefined, early);
    expect(quoted.messages.at(-1)?.text).toBe(routineRepositoryCopy("Launch note", true));
    expect(quoted.routines[0]?.nextRunAt).toBe(launchNext);
    expect(quoted.routines[0]?.recentRuns).toEqual(["2026-10-24T03:00:00.000Z"]);

    const marketAsk = await convene(setPaused(one, true, early), "Which repository starts the Market check routine?", undefined, early);
