    expect(usage.messages.at(-1)?.text).toContain("“Launch note” has no usage pause in the record.");
    expect(usage.messages.at(-1)?.text).not.toContain("repository");
    expect(usage.routines[0]?.paused).toBe(true);
    expect(usage.routines[0]?.nextRunAt).toBe(launchNext);
    expect(usage.routines[0]?.recentRuns).toEqual(["2026-10-24T03:00:00.000Z"]);
