      expect(quiet.routines[0]?.nextRunAt).toBe("2026-10-24T02:00:00.000Z");

      const failure = await convene(quiet, "What failure does the Launch note routine show?", undefined, early);
      expect(failure.messages.at(-1)?.text).toBe(routineFailureCopy("Launch note", true));
      expect(failure.messages.at(-1)?.text).toContain("“Launch note” has no failure in the record.");
      expect(failure.messages.at(-1)?.text).not.toContain("matching rule");
      expect(failure.routines[0]?.paused).toBe(true);
