    expect(asked.messages.at(-1)?.text).toBe(routineLocalComputerAmbiguousCopy("Launch note"));
    expect(asked.messages.at(-1)?.text).toContain("More than one routine has that name");
    expect(asked.messages.at(-1)?.text).not.toContain("has no local-computer refusal");
    expect(asked.messages.at(-1)?.text).not.toContain("Asking does not turn local access on.");
    expect(asked.messages.at(-1)?.text).not.toContain("Market check");
    expect(asked.routines[0]?.heldBack).toEqual(["send"]);
    expect(asked.routines[0]?.paused).toBe(true);
    expect(asked.routines[0]?.instruction).toBe(launchInstruction);
    expect(asked.routines[0]?.nextRunAt).toBe(launchNext);
    expect(asked.routines[0]?.recentRuns).toEqual(["2026-10-24T03:00:00.000Z"]);
    expect(asked.routines[1]?.paused).toBe(true);
    expect(asked.routines[1]?.nextRunAt).toBe(secondNext);
    expect(asked.routines[2]?.paused).not.toBe(true);
    expect(asked.routines[2]?.nextRunAt).toBe(marketNext);
    expect(asked.approvals.find((approval) => approval.goalId === firstId)?.scope).toBe("task");

    for (const text of [
      "Please, is local computer work refused for the Launch note routine.",
      "Is local computer work refused for the Launch note routine??",
    ]) {
      const again = await convene(state, text, undefined, early);
      expect(again.messages.at(-1)?.text).toBe(routineLocalComputerAmbiguousCopy("Launch note"));
      expect(again.routines[0]?.heldBack).toEqual(["send"]);
      expect(again.routines[0]?.paused).toBe(true);
      expect(again.routines[1]?.paused).toBe(true);
      expect(again.routines[2]?.nextRunAt).toBe(marketNext);
      expect(again.goals).toHaveLength(goals);
    }
    const lower = await convene(state, "is local computer work refused for the launch note routine", undefined, early);
    expect(lower.messages.at(-1)?.text).toBe(routineLocalComputerAmbiguousCopy("launch note"));
    expect(lower.messages.at(-1)?.text).not.toContain("has no local-computer refusal");
    expect(lower.routines[0]?.paused).toBe(true);
    expect(lower.routines[1]?.paused).toBe(true);
    expect(lower.routines[2]?.nextRunAt).toBe(marketNext);
    expect(lower.goals).toHaveLength(goals);

    const one = structuredClone(state);
    one.routines.splice(1, 1);
    const named = await convene(one, 'Is local computer work refused for the "Launch note" routine?', undefined, early);
    expect(named.messages.at(-1)?.text).toBe(routineLocalComputerCopy("Launch note", true));
    expect(named.messages.at(-1)?.text).toContain("“Launch note” has no local-computer refusal in the record.");
    expect(named.messages.at(-1)?.text).toContain("Asking does not turn local access on.");
    expect(named.messages.at(-1)?.text).not.toContain("has no source system");
