    expect(asked.routines[2]?.nextRunAt).toBe(marketNext);
    expect(asked.approvals.find((approval) => approval.goalId === firstId)?.scope).toBe("task");

    for (const text of [
      "Please, is the plugin for the Launch note routine authenticated.",
      "Is the plugin for the Launch note routine authenticated??",
    ]) {
      const again = await convene(state, text, undefined, early);
      expect(again.messages.at(-1)?.text).toBe(routinePluginAuthAmbiguousCopy("Launch note"));
      expect(again.routines[0]?.paused).toBe(true);
      expect(again.routines[1]?.paused).toBe(true);
      expect(again.routines[2]?.nextRunAt).toBe(marketNext);
      expect(again.goals).toHaveLength(goals);
    }
    const lower = await convene(state, "is the plugin for the launch note routine authenticated", undefined, early);
    expect(lower.messages.at(-1)?.text).toBe(routinePluginAuthAmbiguousCopy("launch note"));
