    const named = await convene(one, 'Is the app disconnected for the "Launch note" routine?', undefined, early);
    expect(named.messages.at(-1)?.text).toBe(routineDisconnectedAppCopy("Launch note", true));
    expect(named.messages.at(-1)?.text).toContain("“Launch note” has no disconnected app in the record.");
    expect(named.messages.at(-1)?.text).toContain("Asking does not disconnect the app.");
