    const kept = structuredClone(one);
    await expect(convene(kept, "Does a normal recovery for the Launch note routine replace uncommitted state without asking", undefined, early)).rejects.toThrow(/without asking/);
    await expect(convene(kept, "Please does a normal recovery for the Launch note routine replace uncommitted state always allow", undefined, early)).rejects.toThrow(/without asking/);
