    expect(asked.messages.at(-1)?.text).toBe(routineWorkSurfaceAmbiguousCopy("Launch note"));
    expect(asked.messages.at(-1)?.text).toContain("More than one routine has that name");
    expect(asked.messages.at(-1)?.text).not.toContain("has no work surface");
    expect(asked.routines[0]?.heldBack).toEqual(["send"]);
    expect(asked.routines[0]?.paused).toBe(true);
    expect(asked.routines[0]?.instruction).toBe(launchInstruction);
    expect(asked.routines[0]?.nextRunAt).toBe(launchNext);
    expect(asked.routines[1]?.nextRunAt).toBe(secondNext);
    expect(asked.routines[2]?.nextRunAt).toBe(marketNext);

    for (const text of [
      "Please, is a screen for the Launch note routine a separate security boundary.",
      "Is a screen for the Launch note routine a separate security boundary??",
    ]) {
      const again = await convene(state, text, undefined, early);
      expect(again.messages.at(-1)?.text).toBe(routineWorkSurfaceAmbiguousCopy("Launch note"));
      expect(again.routines[0]?.paused).toBe(true);
      expect(again.goals).toHaveLength(goals);
    }
    const lower = await convene(state, "is a screen for the launch note routine a separate security boundary", undefined, early);
    expect(lower.messages.at(-1)?.text).toBe(routineWorkSurfaceAmbiguousCopy("launch note"));
    expect(lower.messages.at(-1)?.text).not.toContain("has no work surface");

    const one = structuredClone(state);
