    const named = await convene(one, 'Is a screen for the "Launch note" routine a separate security boundary?', undefined, early);
    expect(named.messages.at(-1)?.text).toBe(routineWorkSurfaceCopy("Launch note", true));
    expect(named.messages.at(-1)?.text).toContain("Asking does not merge the screens.");
    expect(named.routines[0]?.paused).toBe(true);
    expect(named.routines[0]?.nextRunAt).toBe(launchNext);
    expect(named.routines[1]?.nextRunAt).toBe(marketNext);

    const quoted = await convene(one, "Is a screen for the “Launch note” routine a separate security boundary?", undefined, early);
