    const kept = structuredClone(one);
    await expect(convene(kept, "Is isolation between users strict for the Launch note routine without asking", undefined, early)).rejects.toThrow(/without asking/);
    await expect(convene(kept, "Please is isolation between users strict for the Launch note routine always allow", undefined, early)).rejects.toThrow(/without asking/);
    await expect(convene(kept, "Is isolation between users strict for the Launch note routine and allow for this site", undefined, early)).rejects.toThrow(/without asking/);
