    const none = await convene(initialState(), "Does the Launch note routine keep its own kernel?", undefined, early);
    expect(none.goals).toHaveLength(0);
    expect(none.routines).toHaveLength(0);
    expect(none.messages.at(-1)?.text).toBe(routineGuestSliceMissCopy("Launch note"));
    expect(none.events.some((event) => event.type === "routine_guest_slice")).toBe(true);

    let state = await convene(initialState(), "Email Maya the launch update", undefined, early);
