    expect(aside.messages.at(-1)?.text).not.toContain("has no team bench");
    expect(aside.messages.at(-1)?.text).not.toContain("Asking does not share a team bot.");
    expect(aside.routines[0]?.paused).toBe(true);
    expect(aside.routines[0]?.nextRunAt).toBe(launchNext);

    const near = await convene(one, "Does the Launch notes routine share a cloud-hosted bot with everyone on the team?", undefined, early);
    expect(near.goals).toHaveLength(one.goals.length);
    expect(near.messages.at(-1)?.text).toBe(routineTeamBenchMissCopy("Launch notes"));
