    const now = new Date("2026-10-24T07:00:00.000Z");
    const early: Deps = { now: () => now, fetchImpl: fetch, refine: null };
    const none = await convene(initialState(), "Does the Launch note routine work on that member's computer in that member's own chat or Slack DM?", undefined, early);
    expect(none.goals).toHaveLength(0);
    expect(none.routines).toHaveLength(0);
    expect(none.messages.at(-1)?.text).toBe(routineDirectDeskMissCopy("Launch note"));
    expect(none.events.some((event) => event.type === "routine_direct_desk")).toBe(true);

    let state = await convene(initialState(), "Email Maya the launch update", undefined, early);
