    await expect(convene(kept, "Does the Launch note routine make secrets, apps, and files the owner or a Manager adds to a Team Bot available in every teammate's chat?", "goal_missing", early)).rejects.toThrow(/not in the record/);

    const meterLeft = await convene(one, "Does the Launch note routine use that member's connected accounts after asking and that member's Grok Bot usage?", undefined, early);
