    const kept = structuredClone(one);
    await expect(convene(kept, "Does the Launch note routine keep the Cloud Agents switch on the Grok Bot page for the whole team and on by default without asking", undefined, early)).rejects.toThrow(/without asking/);
    await expect(convene(kept, "Please does the Launch note routine keep the Cloud Agents switch on the Grok Bot page for the whole team and on by default always allow", undefined, early)).rejects.toThrow(/without asking/);
