    expect(kept.routines[0]?.heldBack).toEqual(["send"]);
    expect(kept.goals).toHaveLength(one.goals.length);
    await expect(convene(kept, "Does the Launch note routine keep the Cloud Agents switch on the Grok Bot page for the whole team and on by default?", "goal_missing", early)).rejects.toThrow(/not in the record/);

    const sealedLeft = await convene(one, "Does the Launch note routine keep each member's chat private, including from the owner and the Bot's Managers?", undefined, early);
    expect(sealedLeft.messages.at(-1)?.text).toContain("has no sealed chat");
    expect(sealedLeft.messages.at(-1)?.text).not.toContain("has no default switch");
    const why = await convene(one, "Why hasn't the Launch note routine run?", undefined, early);
    expect(why.messages.at(-1)?.text).toContain("It is paused.");
    expect(why.messages.at(-1)?.text).not.toContain("default switch");
