    const quoted = await convene(one, `Does the “Launch note” routine say ${ADMIN_CHAIR_QUESTION}?`, undefined, early);
    expect(quoted.messages.at(-1)?.text).toBe(routineAdminChairCopy("Launch note", true));
    expect(quoted.routines[0]?.recentRuns).toEqual(["2026-10-24T03:00:00.000Z"]);

    const marketAsk = await convene(setPaused(one, true, early), `Does the Market check routine say ${ADMIN_CHAIR_QUESTION}?`, undefined, early);
