    expect(mercyLower.messages.at(-1)?.text).not.toContain("has no drift landing");
    expect(mercyLower.messages.at(-1)?.text).not.toContain("Asking does not slide that ending past the mark.");
    const lateLower = await convene(state, "does the launch note routine say that computers already past 30 days are included", undefined, early);
    expect(lateLower.messages.at(-1)?.text).toBe(routineLateCohortAmbiguousCopy("launch note"));
    expect(lateLower.messages.at(-1)?.text).not.toContain("has no drift landing");
    expect(lateLower.messages.at(-1)?.text).not.toContain("Asking does not slide that ending past the mark.");

    const one = structuredClone(state);
    one.routines.splice(1, 1);
    const named = await convene(one, `Does the "Launch note" routine say ${DRIFT_LANDING_QUESTION}?`, undefined, early);
    expect(named.messages.at(-1)?.text).toBe(routineDriftLandingCopy("Launch note", true));
    expect(named.routines[0]?.paused).toBe(true);
    expect(named.routines[0]?.nextRunAt).toBe(launchNext);
    expect(named.routines[1]?.nextRunAt).toBe(marketNext);

    const quoted = await convene(one, `Does the “Launch note” routine say ${DRIFT_LANDING_QUESTION}?`, undefined, early);
