      expect(state.messages.at(-1)?.text).toBe(routineFreshBootCopy("Launch note", true));
      expect(state.messages.at(-1)?.text).toContain("“Launch note” has no fresh boot in the record.");
      expect(state.messages.at(-1)?.text).toContain("Asking does not open a new machine on that disk after an ending.");
      expect(state.messages.at(-1)?.text).not.toContain("Asking does not spin up a new machine on that disk after an ending.");
      expect(state.messages.at(-1)?.text).not.toContain("Asking does not bring up a new machine on that disk after an ending.");
